sub('site/leitung/assets/app.js',
 'function initializeEvents(){initializeFeatures',
 "function renderInternalTracking(record,container){container.replaceChildren();const heading=node('h3','',record.serviceTitle||'Interner Vorgang');const status=node('p','',`Status: ${record.status||'Eingegangen'}`),publicNote=node('p','',record.publicMessage||'Noch keine Rückmeldung der Dienststelle.');container.append(heading,status,publicNote);const feed=node('div','chat-feed'),state=node('p','status-text');container.append(feed);const form=node('form','internal-track-chat'),area=node('textarea');area.required=true;area.maxLength=1200;area.rows=3;area.placeholder='Nachricht an die zuständige Stelle …';const send=node('button','icon-label-button','Nachricht senden');send.type='submit';form.append(area,send,state);container.append(form);const files=(record.attachments||[]);for(const meta of files)container.append(node('p','',`Unterlage beigefügt: ${meta.name}`));const render=rows=>{feed.replaceChildren();for(const m of rows){const card=node('article','chat-message '+(m.sender==='Antragsteller'?'chat-own':'chat-staff'));card.append(node('strong','',m.sender==='Antragsteller'?'Sie':(m.senderName||'Landespolizei Fichtenried')),node('p','',m.body),node('small','',m.createdAt?new Date(m.createdAt).toLocaleString('de-DE'):'Gerade eben'));feed.append(card)}if(!rows.length)feed.append(node('p','chat-empty','Noch keine Nachrichten.'))};const refresh=async()=>render(await spark.internalCitizenMessages({id:record.id,accessCode:record.accessCode}));refresh().catch(err=>state.textContent=errorText(err));internalChatStop();internalChatStop=spark.watchInternalCase({id:record.id,accessCode:record.accessCode},current=>{status.textContent='Status: '+(current.status||'Eingegangen');publicNote.textContent=current.publicMessage||'Noch keine Rückmeldung der Dienststelle.'},render,err=>state.textContent=errorText(err));form.onsubmit=async ev=>{ev.preventDefault();send.disabled=true;try{await spark.sendInternalCitizenMessage({id:record.id,accessCode:record.accessCode,body:area.value});area.value='';await refresh();state.textContent='Nachricht gesendet.'}catch(err){state.textContent=errorText(err)}finally{send.disabled=false}};if(files.length){const dl=node('button','text-action','Unterlagen herunterladen');dl.type='button';dl.onclick=async()=>{try{const all=await spark.internalAttachments(record);all.forEach(file=>{const url=URL.createObjectURL(new Blob([file.bytes],{type:file.type})),a=node('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)})}catch(err){state.textContent=errorText(err)}};container.append(dl)}}\nfunction initializeEvents(){initializeFeatures")
