# Spark adds attachment write, public tracking, internal chat and internal attachment fetching.
sub('site/assets/spark.js',
 "export async function submitInternalTicket({name,rank,badge,subject,details}){await requireCaptcha();await auth.authStateReady();let user=auth.currentUser;if(!user?.isAnonymous){if(user)await authMod.signOut(auth);user=await authMod.signInAnonymously(auth)}await protect();name=String(name||'').trim();rank=String(rank||'').trim();badge=String(badge||'').trim();subject=String(subject||'').trim();details=String(details||'').trim();if(name.length<2||name.length>100||rank.length<2||rank.length>80||badge.length>60||subject.length<3||subject.length>120||details.length<10||details.length>3000)throw Error('Bitte Name, Rang, Betreff und Sachverhalt vollständig prüfen.');const id=`LF-I-${new Date().getUTCFullYear()}-${hex(8)}`,stamp=now(),batch=f.writeBatch(db);batch.set(ref('internalCases',id),{id,serviceId:'internal',serviceTitle:'Interner Vorgang',ownerUid:user.uid,data:{fullName:name,rank,badge,subject,details},status:'Eingegangen',internalNote:'',submittedAt:stamp,updatedAt:stamp});batch.set(ref('internalTicketLimits',user.uid),{at:stamp,lastId:id});try{await batch.commit()}catch(e){if(e.code==='permission-denied')throw Error('Der interne Vorgang konnte nicht gesendet werden. Bitte Eingaben prüfen oder es später erneut versuchen.');throw e}return {id};}",
 "const INTERNAL_CATEGORIES={perso:['Perso Ticket','Direkter Kontakt zur Personalebene'],stellen:['Internes Stellenausschreiben','Ticket für eine interne Bewerbung'],ausbildung:['Aus- & Fortbildung Ticket','Direkter Kontakt zur Landesausbildungsebene der Polizei'],leitung:['Leitung Ticket','Direkter Kontakt zur Führung der Landespolizei Fichtenried']};\nfunction internalKey(id,code){id=String(id||'').trim().toUpperCase();code=String(code||'').trim().toUpperCase();if(!/^LF-I-[0-9]{4}-[A-F0-9]{16}$/.test(id)||!/^[A-F0-9]{32}$/.test(code))throw Error('Vorgangsnummer oder Zugangscode ist ungültig.');return id+'_'+code;}\nexport async function submitInternalTicket({category='perso',name,rank,badge,subject,details,files:inputFiles=[]}){await requireCaptcha();await auth.authStateReady();let user=auth.currentUser;if(!user?.isAnonymous){if(user)await authMod.signOut(auth);user=(await authMod.signInAnonymously(auth)).user}await protect();name=String(name||'').trim();rank=String(rank||'').trim();badge=String(badge||'').trim();subject=String(subject||'').trim();details=String(details||'').trim();if(!INTERNAL_CATEGORIES[category]||name.length<2||name.length>100||rank.length<2||rank.length>80||badge.length>60||subject.length<3||subject.length>120||details.length<10||details.length>3000)throw Error('Bitte Kategorie, Name, Rang, Betreff und Sachverhalt prüfen.');const files=await prepareFiles([...inputFiles]),attachments=files.map(({chunks,...m})=>({...m,chunkCount:chunks.length})),id=`LF-I-${new Date().getUTCFullYear()}-${hex(8)}`,accessCode=hex(),trackingKey=id+'_'+accessCode,stamp=now(),[serviceTitle,description]=INTERNAL_CATEGORIES[category],batch=f.writeBatch(db),data={fullName:name,rank,badge,subject,details,category};batch.set(ref('internalCases',id),{id,serviceId:'internal',serviceTitle,ownerUid:user.uid,trackingKey,data,attachments,status:'Eingegangen',internalNote:'',submittedAt:stamp,updatedAt:stamp});batch.set(ref('internalReceipts',trackingKey),{id,serviceId:'internal',serviceTitle,ownerUid:user.uid,data,attachments,submittedAt:stamp});files.forEach((file,slot)=>file.chunks.forEach((chunk,index)=>batch.set(f.doc(db,'internalReceipts',trackingKey,'files',String(slot),'chunks',String(index).padStart(2,'0')),{data:chunk})));batch.set(ref('internalTracking',trackingKey),{id,serviceTitle,status:'Eingegangen',publicMessage:'',updatedAt:stamp});batch.set(ref('internalTicketLimits',user.uid),{at:stamp,lastId:id});try{await batch.commit()}catch(e){if(e.code==='permission-denied')throw Error('Der interne Vorgang konnte nicht gesendet werden. Bitte Eingaben prüfen oder es später erneut versuchen.');throw e}return {id,accessCode};}\nexport async function trackInternal({id,accessCode}){await citizen();const key=internalKey(id,accessCode),[t,r]=await Promise.all([f.getDoc(ref('internalTracking',key)),f.getDoc(ref('internalReceipts',key))]);if(!t.exists()||!r.exists())throw Error('Kein passender interner Vorgang gefunden.');return {...dto(t),...dto(r),trackingKey:key,accessCode};}\nexport async function internalCitizenMessages({id,accessCode}){await citizen();const key=internalKey(id,accessCode),s=await f.getDocs(f.query(f.collection(db,'internalTracking',key,'messages'),f.orderBy('createdAt','asc'),f.limit(100)));return s.docs.map(dto)}\nexport function watchInternalCase({id,accessCode},onRecord,onMessages,onError){const key=internalKey(id,accessCode);let active=true,stopRecord=()=>{},stopMessages=()=>{};citizen().then(()=>{if(!active)return;stopRecord=f.onSnapshot(ref('internalTracking',key),s=>{if(!s.exists()){onError(Error('Interner Vorgang nicht gefunden.'));return}onRecord(dto(s))},onError);stopMessages=f.onSnapshot(f.query(f.collection(db,'internalTracking',key,'messages'),f.orderBy('createdAt','asc'),f.limit(100)),s=>onMessages(s.docs.map(dto)),onError)}).catch(onError);return()=>{active=false;stopRecord();stopMessages()}}\nexport async function sendInternalCitizenMessage({id,accessCode,body}){await requireCaptcha();const user=await citizen(),key=internalKey(id,accessCode),text=String(body||'').trim();if(text.length<1||text.length>1200)throw Error('Nachrichten müssen zwischen 1 und 1.200 Zeichen enthalten.');await f.addDoc(f.collection(db,'internalTracking',key,'messages'),{body:text,sender:'Antragsteller',senderUid:user.uid,createdAt:now()});}\nexport async function internalAttachments(record){if(!record.attachments?.length)return [];await citizen();const files=[];for(let slot=0;slot<record.attachments.length;slot++){const m=record.attachments[slot],parts=await Promise.all(Array.from({length:m.chunkCount},(_,i)=>f.getDoc(f.doc(db,'internalReceipts',record.trackingKey,'files',String(slot),'chunks',String(i).padStart(2,'0')))));if(parts.some(p=>!p.exists()))throw Error('Eine Unterlage ist unvollständig gespeichert.');const bytes=new Uint8Array(parts.reduce((n,s)=>n+decode64(s.data().data).length,0));let offset=0;for(const p of parts){const b=decode64(p.data().data);bytes.set(b,offset);offset+=b.length;}const digest=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes)),v=>v.toString(16).padStart(2,'0')).join('');if(bytes.length!==m.size||digest!==m.sha256)throw Error('Prüfsumme einer Unterlage stimmt nicht.');files.push({...m,bytes});}return files;}")
