 "request.resource.data.keys().hasOnly(['id','serviceId','serviceTitle','ownerUid','data','status','internalNote','submittedAt','updatedAt']) && request.resource.data.id==id && request.resource.data.serviceId=='internal' && request.resource.data.serviceTitle=='Interner Vorgang' && request.resource.data.ownerUid==request.auth.uid && request.resource.data.data is map && request.resource.data.data.keys().hasOnly(['fullName','rank','badge','subject','details'])",
