sub('backend/firestore.rules',
 "  match /limits/{uid} {",
 "  match /internalReceipts/{key} {\n   allow get: if signed() && exists(/databases/$(database)/documents/internalTracking/$(key));\n   allow create: if signed() && key.matches('LF-I-[0-9]{4}-[A-F0-9]{16}_[A-F0-9]{32}') && request.resource.data.keys().hasOnly(['id','serviceId','serviceTitle','ownerUid','data','attachments','submittedAt']) && request.resource.data.ownerUid==request.auth.uid && request.resource.data.submittedAt==request.time && getAfter(/databases/$(database)/documents/internalCases/$(request.resource.data.id)).data.ownerUid==request.auth.uid && getAfter(/databases/$(database)/documents/internalCases/$(request.resource.data.id)).data.trackingKey==key && request.resource.data.data==getAfter(/databases/$(database)/documents/internalCases/$(request.resource.data.id)).data.data && request.resource.data.attachments==getAfter(/databases/$(database)/documents/internalCases/$(request.resource.data.id)).data.attachments && request.resource.data.serviceTitle==getAfter(/databases/$(database)/documents/internalCases/$(request.resource.data.id)).data.serviceTitle;\n   match /files/{slot}/chunks/{chunk} {\n    allow get: if signed() && exists(/databases/$(database)/documents/internalTracking/$(key));\n    allow create: if signed() && slot in ['0','1','2'] && chunk.matches('0[01]') && getAfter(/databases/$(database)/documents/internalReceipts/$(key)).data.ownerUid==request.auth.uid && getAfter(/databases/$(database)/documents/internalReceipts/$(key)).data.submittedAt==request.time && int(slot)<getAfter(/databases/$(database)/documents/internalReceipts/$(key)).data.attachments.size() && int(chunk)<getAfter(/databases/$(database)/documents/internalReceipts/$(key)).data.attachments[int(slot)].chunkCount && request.resource.data.keys().hasOnly(['data']) && request.resource.data.data is string && request.resource.data.data.size()>0 && request.resource.data.data.size()<=737280 && chunkValid(request.resource.data.data,getAfter(/databases/$(database)/documents/internalReceipts/$(key)).data.attachments[int(slot)],chunk);\n   }\n  }\n  match /internalTracking/{key} {\n   allow get: if signed() && key.matches('LF-I-[0-9]{4}-[A-F0-9]{16}_[A-F0-9]{32}');\n   allow create: if signed() && request.auth.token.firebase.sign_in_provider=='anonymous' && request.resource.data.keys().hasOnly(['id','serviceTitle','status','publicMessage','updatedAt']) && request.resource.data.id.matches('LF-I-[0-9]{4}-[A-F0-9]{16}') && key.matches(request.resource.data.id+'_[A-F0-9]{32}') && getAfter(/databases/$(database)/documents/internalCases/$(request.resource.data.id)).data.ownerUid==request.auth.uid && getAfter(/databases/$(database)/documents/internalCases/$(request.resource.data.id)).data.trackingKey==key && request.resource.data.serviceTitle==getAfter(/databases/$(database)/documents/internalCases/$(request.resource.data.id)).data.serviceTitle && request.resource.data.status=='Eingegangen' && request.resource.data.publicMessage=='' && request.resource.data.updatedAt==request.time;\n   allow update: if cases() && request.resource.data.diff(resource.data).affectedKeys().hasOnly(['status','publicMessage','updatedAt']) && request.resource.data.updatedAt==request.time && status(request.resource.data.status) && request.resource.data.publicMessage is string && request.resource.data.publicMessage.size()<=2000 && getAfter(/databases/$(database)/documents/internalCases/$(resource.data.id)).data.updatedAt==request.time;\n   match /messages/{messageId} {\n    allow read: if signed() && exists(/databases/$(database)/documents/internalTracking/$(key));\n    allow create: if signed() && exists(/databases/$(database)/documents/internalTracking/$(key)) && request.resource.data.body is string && request.resource.data.body.size()>=1 && request.resource.data.body.size()<=1200 && request.resource.data.createdAt==request.time && request.resource.data.senderUid==request.auth.uid && ((request.resource.data.sender=='Antragsteller' && request.auth.token.firebase.sign_in_provider=='anonymous' && request.resource.data.keys().hasOnly(['body','sender','senderUid','createdAt'])) || (request.resource.data.sender=='Polizei' && cases() && request.resource.data.keys().hasOnly(['body','sender','senderUid','senderName','createdAt','auditId']) && request.resource.data.senderName is string && request.resource.data.senderName.size()<=80 && audit(request.resource.data.auditId,'case_chat_message',get(/databases/$(database)/documents/internalTracking/$(key)).data.id)));\n    allow update,delete: if false;\n   }\n  }\n  match /limits/{uid} {")
